window.EXPERIMENTS = [{"id": "experiment-1", "url": "pwm-adc.html", "title": "PWM & ADC Speed Control", "description": "Blink a pin with different pulse widths, then set motor speed from a potentiometer through the ADC.", "level": 1, "icon": "<svg viewBox=\"0 0 200 100\"><polyline points=\"10,70 30,70 30,30 60,30 60,70 70,70 70,30 100,30 100,70 110,70 110,30 140,30 140,70 150,70 150,30 180,30 180,70 190,70\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"4\"/></svg>"}, {"id": "experiment-2", "url": "line-follower.html?fw=LFR", "title": "Line Follower Robot", "description": "Two IR sensors straddle a black line; beeps at crossings.", "level": 1, "icon": "<svg viewBox=\"0 0 200 100\"><path d=\"M20,80 C60,80 60,20 100,20 S140,80 180,80\" fill=\"none\" stroke=\"#111\" stroke-width=\"9\"/><rect x=\"88\" y=\"10\" width=\"26\" height=\"20\" rx=\"4\" fill=\"#1f7a4d\"/></svg>"}, {"id": "experiment-3", "url": "obstacle-avoider.html", "title": "Obstacle Avoider Robot", "description": "Three proximity sensors and a timed escape manoeuvre for every obstacle pattern.", "level": 1, "icon": "<svg viewBox=\"0 0 200 100\"><rect x=\"120\" y=\"25\" width=\"40\" height=\"40\" fill=\"#e8833a\"/><rect x=\"50\" y=\"40\" width=\"30\" height=\"22\" rx=\"4\" fill=\"#2563eb\"/><path d=\"M80,51 L118,38 L118,64 Z\" fill=\"rgba(220,38,38,0.25)\"/></svg>"}, {"id": "experiment-4", "url": "line-follower.html?fw=OARLFR", "title": "Obstacle Avoiding Line Follower", "description": "Follows the line and waits whenever something blocks the path.", "level": 1, "icon": "<svg viewBox=\"0 0 200 100\"><line x1=\"10\" y1=\"60\" x2=\"190\" y2=\"60\" stroke=\"#111\" stroke-width=\"9\"/><rect x=\"130\" y=\"40\" width=\"24\" height=\"24\" fill=\"#e8833a\"/><rect x=\"70\" y=\"49\" width=\"30\" height=\"22\" rx=\"4\" fill=\"#1f7a4d\"/></svg>"}, {"id": "experiment-5", "url": "table-top.html", "title": "Table Top Robot", "description": "Four edge sensors keep it from driving off the table.", "level": 1, "icon": "<svg viewBox=\"0 0 200 100\"><rect x=\"0\" y=\"0\" width=\"200\" height=\"100\" fill=\"#3b3f46\"/><rect x=\"30\" y=\"15\" width=\"140\" height=\"70\" fill=\"#c99a62\"/><rect x=\"120\" y=\"35\" width=\"34\" height=\"24\" rx=\"4\" fill=\"#7c3aed\"/></svg>"}, {"id": "experiment-6", "url": "serial-control.html?fw=TTL", "title": "Serial Communication (TTL dongle)", "description": "Drive the robot from a PC terminal over the UART, one character at a time.", "level": 1, "icon": "<svg viewBox=\"0 0 200 100\"><text x=\"30\" y=\"62\" font-family=\"monospace\" font-size=\"34\" fill=\"#16a34a\">F B L R</text></svg>"}, {"id": "experiment-7", "url": "line-follower.html?fw=ALFR", "title": "Advanced Line Follower (competition)", "description": "Junction beeps, obstacle alarm and potentiometer-set slow speed inside caves.", "level": 1, "icon": "<svg viewBox=\"0 0 200 100\"><rect x=\"60\" y=\"20\" width=\"80\" height=\"12\" fill=\"#64748b\"/><rect x=\"60\" y=\"68\" width=\"80\" height=\"12\" fill=\"#64748b\"/><line x1=\"10\" y1=\"50\" x2=\"190\" y2=\"50\" stroke=\"#111\" stroke-width=\"9\"/><rect x=\"85\" y=\"40\" width=\"30\" height=\"22\" rx=\"4\" fill=\"#1f7a4d\"/></svg>"}, {"id": "experiment-8", "url": "serial-control.html?fw=WC", "title": "Bluetooth Wheelchair (final project)", "description": "Phone-controlled over HC-05, stops and backs off when the ultrasonic sensor sees an obstacle.", "level": 1, "icon": "<svg viewBox=\"0 0 200 100\"><rect x=\"40\" y=\"35\" width=\"40\" height=\"30\" rx=\"5\" fill=\"#0f766e\"/><path d=\"M80,50 A70,70 0 0 1 150,20 M80,50 A70,70 0 0 0 150,80\" fill=\"none\" stroke=\"#94a3b8\" stroke-width=\"3\"/><rect x=\"160\" y=\"20\" width=\"14\" height=\"60\" fill=\"#e8833a\"/></svg>"}, {"id": "experiment-9", "url": "gesture.html?fw=RFRemote", "title": "Gesture & RF Remote Control", "description": "Tilt a virtual MEMS accelerometer; the remote sends letters, the robot drives.", "level": 2, "icon": "<svg viewBox=\"0 0 200 100\"><rect x=\"30\" y=\"30\" width=\"50\" height=\"40\" rx=\"6\" fill=\"#334155\"/><path d=\"M95,50 q10,-12 20,0 q10,12 20,0\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"4\"/><rect x=\"145\" y=\"38\" width=\"30\" height=\"24\" rx=\"4\" fill=\"#b45309\"/></svg>"}, {"id": "experiment-10", "url": "gesture.html?fw=ArmRemote", "title": "Gesture Pick & Place Robot", "description": "Steer by tilt, work the lift and gripper with switches, carry the block to the drop zone.", "level": 2, "icon": "<svg viewBox=\"0 0 200 100\"><rect x=\"40\" y=\"50\" width=\"50\" height=\"30\" rx=\"5\" fill=\"#b45309\"/><path d=\"M80,55 L120,30 L150,45\" fill=\"none\" stroke=\"#475569\" stroke-width=\"7\" stroke-linecap=\"round\"/><circle cx=\"160\" cy=\"62\" r=\"10\" fill=\"#ea580c\"/></svg>"}, {"id": "experiment-11", "url": "serial-control.html?fw=ComputerControlled", "title": "Computer Controlled Robot", "description": "Keyboard control of the chassis and a two-joint arm, with an LCD showing each key.", "level": 2, "icon": "<svg viewBox=\"0 0 200 100\"><rect x=\"30\" y=\"20\" width=\"80\" height=\"55\" rx=\"4\" fill=\"#334155\"/><text x=\"42\" y=\"55\" font-family=\"monospace\" font-size=\"20\" fill=\"#a7f3d0\">wasd</text><rect x=\"130\" y=\"45\" width=\"40\" height=\"28\" rx=\"4\" fill=\"#1f7a4d\"/></svg>"}, {"id": "experiment-12", "url": "maze.html?mode=explore", "title": "Maze Solving Robot", "description": "Five line sensors and the left hand rule; records every junction decision.", "level": 2, "icon": "<svg viewBox=\"0 0 200 100\"><path d=\"M30,80 V20 H90 V50 H130 V20 H170 V80 M90,50 V80 H130\" fill=\"none\" stroke=\"#111\" stroke-width=\"7\"/><rect x=\"160\" y=\"70\" width=\"20\" height=\"20\" fill=\"#111\"/></svg>"}, {"id": "experiment-13", "url": "maze.html?mode=replay", "title": "Shortest Path Algorithm", "description": "Removes every dead-end detour from the recorded path, then runs the maze perfectly.", "level": 2, "icon": "<svg viewBox=\"0 0 200 100\"><text x=\"18\" y=\"45\" font-family=\"monospace\" font-size=\"20\" fill=\"#64748b\">LUSLUSLLUL</text><text x=\"60\" y=\"80\" font-family=\"monospace\" font-size=\"24\" fill=\"#16a34a\">&#8594; RRRR</text></svg>"}, {"id": "experiment-14", "url": "maze.html?mode=return", "title": "Maze Return Assignment", "description": "After solving the maze, reverse and mirror the path and drive back to the start.", "level": 2, "icon": "<svg viewBox=\"0 0 200 100\"><path d=\"M40,70 H160\" stroke=\"#111\" stroke-width=\"7\"/><path d=\"M150,40 H60 l12,-10 M60,40 l12,10\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"4\"/></svg>"}, {"id": "experiment-15", "url": "tachometer.html", "title": "Tachometer", "description": "Count IR pulses from a spinning shaft and show the RPM on a 16x2 LCD.", "level": 2, "icon": "<svg viewBox=\"0 0 200 100\"><circle cx=\"100\" cy=\"55\" r=\"38\" fill=\"#1f2937\"/><path d=\"M100,55 L100,17 A38,38 0 0 1 116,20 Z\" fill=\"#f8fafc\"/><rect x=\"88\" y=\"2\" width=\"24\" height=\"12\" fill=\"#ef4444\"/></svg>"}];
window.EXPERIMENT_DOCUMENTS = {"pwm-adc.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>PWM &amp; ADC Speed Control - Kaizen Robotics live demo</title>\n<link rel=\"stylesheet\" href=\"assets/style.css\">\n<style>\n    .row { display: grid; grid-template-columns: 170px 1fr; gap: 14px; align-items: center; }\n    .scope { width: 100%; height: auto; border-radius: 8px; display: block; }\n    #led { width: 120px; height: 120px; border-radius: 50%; margin: 6px auto; border: 4px solid #7f1d1d; background: #3b0d0d; transition: background 0.03s, box-shadow 0.03s; }\n    #led.on { background: #ef4444; box-shadow: 0 0 40px 12px rgba(239,68,68,0.6); }\n    #wheel { width: 160px; height: 160px; display: block; margin: 0 auto; }\n    .meter { height: 14px; background: var(--code); border-radius: 7px; overflow: hidden; }\n    .meter i { display: block; height: 100%; background: var(--accent); width: 0; }\n</style>\n</head>\n<body>\n<header class=\"top\">\n    <a class=\"crumb\" href=\"index.html\">&larr; All demos</a>\n    <h1>PWM &amp; ADC Based Speed Control</h1>\n    <span class=\"tag\">Level 1 &middot; ATmega16 &middot; Embedded C</span>\n</header>\n<p class=\"lede\">\n    Pulse width modulation switches a pin fully on and off so fast that a motor or LED only \"feels\" the average.\n    The longer the ON part of each period (the duty cycle), the brighter the LED or the faster the motor.\n    The ADC lab sets the duty cycle from a potentiometer.\n</p>\n\n<main class=\"demo\">\n    <div>\n        <div class=\"panel\">\n            <div class=\"toolbar\" id=\"toolbar\"></div>\n            <h2>1. Pulse width modulation &ndash; <code>PWM.c</code></h2>\n            <div class=\"row\">\n                <div id=\"led\"></div>\n                <canvas class=\"scope\" id=\"scopeA\" width=\"900\" height=\"150\"></canvas>\n            </div>\n            <p class=\"hint\">PA0 alternates between a fast 50 ms / 50 ms pulse and a slow 1 s / 1 s pulse (3 s scope window).</p>\n        </div>\n        <div class=\"panel\">\n            <h2>2. ADC based speed control &ndash; <code>SpeedCntrl.c</code></h2>\n            <div class=\"slider\">\n                <span>Potentiometer</span>\n                <input type=\"range\" id=\"pot\" min=\"0\" max=\"1023\" value=\"400\">\n                <code id=\"potVal\"></code>\n            </div>\n            <div class=\"row\" style=\"margin-top:12px\">\n                <canvas id=\"wheel\" width=\"320\" height=\"320\"></canvas>\n                <canvas class=\"scope\" id=\"scopeB\" width=\"900\" height=\"150\"></canvas>\n            </div>\n            <dl class=\"kv\" style=\"margin-top:10px\">\n                <dt>ADC reading</dt><dd id=\"adc\"></dd>\n                <dt>OFF time = ADC / 40</dt><dd id=\"toff\"></dd>\n                <dt>ON time = 25 &minus; OFF</dt><dd id=\"ton\"></dd>\n                <dt>Duty cycle</dt><dd><div class=\"meter\"><i id=\"duty\"></i></div><span id=\"dutyTxt\"></span></dd>\n                <dt>Motor speed</dt><dd id=\"rpm\"></dd>\n            </dl>\n        </div>\n    </div>\n    <aside>\n        <div class=\"panel\">\n            <h2>Registers</h2>\n            <div id=\"regA\"></div>\n            <div id=\"regB\"></div>\n        </div>\n        <div class=\"panel\" id=\"logicA\"></div>\n        <div class=\"panel\" id=\"logicB\"></div>\n    </aside>\n</main>\n\n<section class=\"explain\">\n    <h2>How it works</h2>\n    <ol>\n        <li><b>PWM.c</b> drives PA0 high, waits with <code>_delay_ms()</code>, drives it low and waits again. The two\n            timings show how the pulse width changes what you see.</li>\n        <li><b>SpeedCntrl.c</b> sets up the ADC (<code>ADEN</code>, prescaler /16, AVCC reference) and starts a conversion\n            with <code>ADSC</code>. When <code>ADIF</code> is set the 10-bit result (0&ndash;1023) is in <code>ADC</code>.</li>\n        <li>The reading sets the OFF time of a 25 ms software PWM period: <code>t_off = reading / 40</code>,\n            <code>t_on = 25 - t_off</code>. A higher reading means a longer OFF time and a slower motor.</li>\n        <li>At 870 and above the motors are switched off completely.</li>\n        <li>Because <code>_delay_ms()</code> needs a constant, the cleaned-up code waits 1 ms at a time in a loop.</li>\n    </ol>\n</section>\n\n<script src=\"assets/kaizen.js\"></script>\n<script src=\"assets/firmware.js\"></script>\n<script>\n(function () {\n    const K = Kaizen, F = KaizenFirmware;\n    const regA = K.registerView(document.getElementById('regA'), 'PORTA (PWM.c)', { 0: 'PA0 LED' });\n    const regB = K.registerView(document.getElementById('regB'), 'PORTB (SpeedCntrl.c)', { 1: 'PB1 right motor fwd', 3: 'PB3 left motor fwd' });\n    const tableA = K.decisionTable(document.getElementById('logicA'), 'PWM.c main loop', [\n        { id: 'short', when: '50 / 50 ms', meaning: 'Short pulse', action: 'PA0 on 50 ms, off 50 ms' },\n        { id: 'long', when: '1 s / 1 s', meaning: 'Long pulse', action: 'PA0 on 1 s, off 1 s' },\n    ], K.source('Level 1/PWM/PWM.c'));\n    const tableB = K.decisionTable(document.getElementById('logicB'), 'SpeedCntrl.c main loop', [\n        { id: 'pwm', when: 'ADC &lt; 870', meaning: 'Run', action: 'Forward for t_on, stop for t_off' },\n        { id: 'stop', when: 'ADC &ge; 870', meaning: 'Pot turned up fully', action: 'Motors off' },\n    ], K.source('Level 1/ADC Based Speed Control/SpeedCntrl.c'));\n\n    const pot = document.getElementById('pot');\n    const ioA = { porta: 0, trace: null }, ioB = { portb: 0, trace: null };\n    ioA.PORTA = v => { ioA.porta = v; };\n    ioA.trace = id => { ioA.traceId = id; };\n    ioB.PORTB = v => { ioB.portb = v; };\n    ioB.readADC = () => +pot.value;\n    ioB.trace = id => { ioB.traceId = id; };\n    let fwA, fwB;\n    const restart = () => { fwA = new K.Firmware(F.PWM, ioA); fwB = new K.Firmware(F.SpeedCntrl, ioB); };\n    restart();\n\n    const scopeA = K.scope(document.getElementById('scopeA'), [{ name: 'PA0', color: '#f87171' }], 3000);\n    const scopeB = K.scope(document.getElementById('scopeB'), [{ name: 'PB3/PB1 motor', color: '#4ade80' }], 150);\n    const motor = { speed: 0, angle: 0 };\n    const sim = { t: 0, speed: 1, running: true };\n\n    const wheel = document.getElementById('wheel'), wctx = wheel.getContext('2d');\n    function drawWheel() {\n        const c = wheel.width / 2;\n        wctx.clearRect(0, 0, wheel.width, wheel.height);\n        wctx.save();\n        wctx.translate(c, c);\n        wctx.rotate(motor.angle);\n        wctx.fillStyle = '#1f2937';\n        wctx.beginPath(); wctx.arc(0, 0, c - 10, 0, Math.PI * 2); wctx.fill();\n        wctx.fillStyle = '#facc15';\n        wctx.beginPath(); wctx.arc(0, 0, c - 50, 0, Math.PI * 2); wctx.fill();\n        wctx.strokeStyle = '#1f2937'; wctx.lineWidth = 12;\n        for (let i = 0; i < 5; i++) {\n            wctx.rotate(Math.PI * 2 / 5);\n            wctx.beginPath(); wctx.moveTo(0, 0); wctx.lineTo(c - 52, 0); wctx.stroke();\n        }\n        wctx.fillStyle = '#9ca3af';\n        wctx.beginPath(); wctx.arc(0, 0, 16, 0, Math.PI * 2); wctx.fill();\n        wctx.restore();\n    }\n\n    let last = null;\n    function frame(now) {\n        if (last === null) last = now;\n        const dt = Math.min(50, now - last);\n        last = now;\n        if (sim.running) {\n            const ticks = Math.round(dt * sim.speed);\n            for (let i = 0; i < ticks; i++) {\n                sim.t++;\n                fwA.step(sim.t);\n                fwB.step(sim.t);\n                const on = (ioB.portb & 0b1010) ? 1 : 0;\n                motor.speed += (on - motor.speed) * (1 - Math.exp(-0.001 / 0.12));    // motor inertia\n                motor.angle += motor.speed * 0.012;\n                scopeA.push(sim.t, [ioA.porta & 1]);\n                scopeB.push(sim.t, [on]);\n            }\n        }\n        scopeA.draw(sim.t);\n        scopeB.draw(sim.t);\n        drawWheel();\n        document.getElementById('led').classList.toggle('on', !!(ioA.porta & 1));\n        regA.update(ioA.porta);\n        regB.update(ioB.portb);\n        tableA.highlight(ioA.traceId);\n        tableB.highlight(ioB.traceId);\n        const r = +pot.value, toff = Math.floor(r / 40), ton = 25 - toff, run = r < 870;\n        document.getElementById('potVal').textContent = r;\n        document.getElementById('adc').textContent = r;\n        document.getElementById('toff').textContent = toff + ' ms';\n        document.getElementById('ton').textContent = ton + ' ms';\n        const duty = run ? ton / 25 : 0;\n        document.getElementById('duty').style.width = duty * 100 + '%';\n        document.getElementById('dutyTxt').textContent = run ? Math.round(duty * 100) + '%' : '0% (stopped, reading >= 870)';\n        document.getElementById('rpm').textContent = Math.round(motor.speed * 200) + ' RPM (200 RPM motor)';\n        requestAnimationFrame(frame);\n    }\n    requestAnimationFrame(frame);\n    K.toolbar(document.getElementById('toolbar'), sim, { sound: false, onReset: restart });\n})();\n</script>\n</body>\n</html>\n", "line-follower.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Line Followers - Kaizen Robotics live demo</title>\n<link rel=\"stylesheet\" href=\"assets/style.css\">\n</head>\n<body>\n<header class=\"top\">\n    <a class=\"crumb\" href=\"index.html\">&larr; All demos</a>\n    <h1>Line Following Robots</h1>\n    <span class=\"tag\">Level 1 &middot; ATmega16 &middot; Embedded C</span>\n</header>\n<p class=\"lede\">\n    Two IR sensors straddle a black line. Each loop the firmware reads <code>PIND</code>, matches the bit\n    pattern against its cases and writes a motor pattern to <code>PORTB</code>. Pick a firmware to compare\n    the basic line follower with the obstacle-aware and competition versions.\n</p>\n\n<main class=\"demo\">\n    <div>\n        <div class=\"panel stage\">\n            <div class=\"toolbar\" id=\"toolbar\">\n                <label class=\"speed\">Firmware <select id=\"fw\"></select></label>\n            </div>\n            <canvas id=\"world\" width=\"1350\" height=\"840\"></canvas>\n            <p class=\"hint\" id=\"hint\"></p>\n            <div class=\"slider\" id=\"potRow\" style=\"margin-top:8px\">\n                <span>Cave speed pot (ADC0)</span>\n                <input type=\"range\" id=\"pot\" min=\"0\" max=\"1023\" value=\"600\">\n                <code id=\"potVal\"></code>\n            </div>\n        </div>\n    </div>\n    <aside>\n        <div class=\"panel\" id=\"io\">\n            <h2>Microcontroller I/O</h2>\n            <div id=\"inReg\"></div>\n            <div id=\"outReg\"></div>\n            <dl class=\"kv\" id=\"pins\" hidden></dl>\n            <h3>Motors</h3>\n            <div id=\"motors\"></div>\n            <p class=\"hint\" id=\"caveState\"></p>\n        </div>\n        <div class=\"panel\" id=\"logic\"></div>\n    </aside>\n</main>\n\n<section class=\"explain\">\n    <h2>How it works</h2>\n    <ol>\n        <li>Each line sensor shines IR at the floor. White reflects (reads <b>0</b>), the black line absorbs it (reads <b>1</b>).</li>\n        <li>The sensors sit either side of the line, so on a straight both read 0 and the robot drives forward.</li>\n        <li>When the line curves it slides under one sensor; the robot spins towards that side until the line is centred again.</li>\n        <li>When both sensors see black the robot is on a crossing: it beeps and drives straight over it.</li>\n    </ol>\n    <h2>Firmware variants</h2>\n    <ul>\n        <li><b>LFR.c</b> &ndash; the basic two-sensor line follower.</li>\n        <li><b>OARLFR.c</b> &ndash; adds a front proximity sensor on PD1 and waits while the path is blocked.</li>\n        <li><b>ALFR.c</b> &ndash; competition robot: stops with an alarm at obstacles and runs at a potentiometer-set\n            PWM speed while its side sensor sees a cave wall.</li>\n        <li><b>ALFR(Arduino).ino</b> &ndash; the same behaviour written with the Arduino API and <code>analogWrite()</code>.</li>\n    </ul>\n    <h2>Try this</h2>\n    <ul>\n        <li>Click on the track in front of the robot to drop an obstacle (obstacle-aware firmware only). Click it again to remove it.</li>\n        <li>Drag the robot to move it, or drag the blue dot to turn it. Put it on the line at an angle and watch it recover.</li>\n        <li>With ALFR.c, move the cave pot: higher readings mean a longer PWM off-time and a slower robot in the cave.</li>\n    </ul>\n</section>\n\n<script src=\"assets/kaizen.js\"></script>\n<script src=\"assets/firmware.js\"></script>\n<script src=\"assets/rigs.js\"></script>\n<script>\n(function () {\n    const K = Kaizen, R = KaizenRigs;\n    const SOURCES = {\n        LFR: 'Level 1/Line Follower Robot/LFR.c',\n        OARLFR: 'Level 1/OAR + LFR/OARLFR.c',\n        ALFR: 'Level 1/Line Follower Competition/Advanced-Line-Following-Robot-master/ALFR.c',\n        ALFRArduino: 'Level 1/Line Follower Competition/Advanced-Line-Following-Robot-master/ALFR(Arduino).ino',\n    };\n    const TABLES = {\n        LFR: [\n            { id: 'centred', when: '11111100', meaning: 'Both sensors on white', action: 'Forward' },\n            { id: 'left', when: '11111110', meaning: 'Line under left sensor', action: 'Spin left' },\n            { id: 'right', when: '11111101', meaning: 'Line under right sensor', action: 'Spin right' },\n            { id: 'cross', when: '11111111', meaning: 'Both on black (crossing)', action: 'Forward + beep, 200 ms' },\n        ],\n        OARLFR: [\n            { id: 'centred', when: '11111010', meaning: 'Line centred, path clear', action: 'Forward' },\n            { id: 'left', when: '11111011', meaning: 'Line under left sensor', action: 'Spin left' },\n            { id: 'right', when: '11111110', meaning: 'Line under right sensor', action: 'Spin right' },\n            { id: 'cross', when: '11111111', meaning: 'Junction, path clear', action: 'Forward + beep' },\n            { id: 'blocked', when: '111111x0x', meaning: 'PD1 = 0: obstacle ahead', action: 'Stop and wait' },\n        ],\n        ALFR: [\n            { id: 'centred', when: '1111x100', meaning: 'Both sensors on white', action: 'Forward' },\n            { id: 'left', when: '1111x110', meaning: 'Line under left sensor', action: 'Spin left' },\n            { id: 'right', when: '1111x101', meaning: 'Line under right sensor', action: 'Spin right' },\n            { id: 'cross', when: '1111x111', meaning: 'Both on black (crossing)', action: 'Forward + beep' },\n            { id: 'obstacle', when: '1111x000', meaning: 'PD2 = 0: obstacle ahead', action: 'Stop, buzzer on' },\n        ],\n        ALFRArduino: [\n            { id: 'obstacle', when: 'D17 = 0', meaning: 'Obstacle ahead', action: 'Stop, buzzer on' },\n            { id: 'centred', when: 'L=0 R=0', meaning: 'Both sensors on white', action: 'Forward' },\n            { id: 'left', when: 'L=1 R=0', meaning: 'Line under left sensor', action: 'Spin left' },\n            { id: 'right', when: 'L=0 R=1', meaning: 'Line under right sensor', action: 'Spin right' },\n            { id: 'cross', when: 'L=1 R=1', meaning: 'Both on black (crossing)', action: 'Forward + beep' },\n        ],\n    };\n\n    const fwSelect = document.getElementById('fw');\n    for (const [key, fw] of Object.entries(R.LINE_FIRMWARE)) fwSelect.append(new Option(fw.label, key));\n\n    const pot = document.getElementById('pot');\n    const potVal = document.getElementById('potVal');\n    let rig, sim, inReg, outReg, table, motors;\n\n    function build(name) {\n        const fw = R.LINE_FIRMWARE[name];\n        const placed = rig ? rig.world.obstacles.filter(o => !o.wall) : [];\n        rig = R.lineFollower(name, { adc: +pot.value });\n        if (fw.obstacle) rig.world.obstacles.push(...placed);     // keep placed obstacles\n        document.getElementById('potRow').hidden = !fw.cave;\n        document.getElementById('hint').textContent = fw.obstacle\n            ? 'Click the floor to drop an obstacle, click it again to remove it. Drag the robot to move it, drag the blue dot to rotate it.'\n            : 'Drag the robot to move it, drag the blue dot to rotate it.';\n\n        const inBox = document.getElementById('inReg'), outBox = document.getElementById('outReg');\n        inBox.innerHTML = outBox.innerHTML = '';\n        const pins = document.getElementById('pins');\n        const arduino = name === 'ALFRArduino';\n        pins.hidden = !arduino;\n        inReg = outReg = null;\n        if (!arduino) {\n            inReg = K.registerView(inBox, 'PIND (inputs)', rig.io.labels, 'Unused pins are pulled up and read 1.');\n            outReg = K.registerView(outBox, 'PORTB (outputs)', K.PORTB_LABELS);\n        }\n        const logic = document.getElementById('logic');\n        logic.innerHTML = '';\n        table = K.decisionTable(logic, 'Firmware logic &ndash; ' + fw.label, TABLES[name], K.source(SOURCES[name]));\n        if (sim) { sim.world = rig.world; sim.robot = rig.robot; sim.tick = rig.tick; }\n    }\n\n    const initial = new URLSearchParams(location.search).get('fw');\n    if (R.LINE_FIRMWARE[initial]) fwSelect.value = initial;\n    build(fwSelect.value);\n    motors = K.motorView(document.getElementById('motors'));\n\n    sim = new K.Sim({\n        canvas: document.getElementById('world'),\n        world: rig.world,\n        robot: rig.robot,\n        tick: t => rig.tick(t),\n        onPointer: (type, x, y) => K.obstacleEditor(rig.world, {\n            size: 24, enabled: () => R.LINE_FIRMWARE[fwSelect.value].obstacle,\n        })(type, x, y),\n        onFrame: () => {\n            const io = rig.io, s = rig.robot.readings;\n            if (inReg) inReg.update(io.PIND());\n            if (outReg) outReg.update(rig.portb);\n            if (fwSelect.value === 'ALFRArduino') {\n                document.getElementById('pins').innerHTML =\n                    `<dt>D15 left line</dt><dd>${s.left}</dd><dt>D16 right line</dt><dd>${s.right}</dd>` +\n                    `<dt>D17 obstacle</dt><dd>${s.front ? 0 : 1}</dd><dt>D14 cave</dt><dd>${s.cave ? 0 : 1}</dd>` +\n                    `<dt>analogWrite</dt><dd>${s.cave ? 200 : 255}</dd>`;\n            }\n            motors.update(rig.robot);\n            table.highlight(rig.trace);\n            K.beeper.set(rig.robot.buzzer);\n            const fw = R.LINE_FIRMWARE[fwSelect.value];\n            document.getElementById('caveState').textContent = !fw.cave ? '' :\n                fwSelect.value === 'ALFR'\n                    ? (io.inCave ? `Inside cave: software PWM, on ${25 - Math.floor(io.adc / 40)} ms / off ${Math.floor(io.adc / 40)} ms` + (io.adc > 870 ? ' (pot above 870: full speed)' : '') : 'Outside cave: full speed')\n                    : (s.cave ? 'Inside cave: analogWrite(200)' : 'Outside cave: analogWrite(255)');\n        },\n    });\n\n    K.toolbar(document.getElementById('toolbar'), sim, { onReset: () => build(fwSelect.value) });\n    fwSelect.onchange = () => build(fwSelect.value);\n    const showPot = () => { potVal.textContent = pot.value; rig.io.adc = +pot.value; };\n    pot.oninput = showPot;\n    showPot();\n})();\n</script>\n</body>\n</html>\n", "obstacle-avoider.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Obstacle Avoider - Kaizen Robotics live demo</title>\n<link rel=\"stylesheet\" href=\"assets/style.css\">\n</head>\n<body>\n<header class=\"top\">\n    <a class=\"crumb\" href=\"index.html\">&larr; All demos</a>\n    <h1>Obstacle Avoider Robot</h1>\n    <span class=\"tag\">Level 1 &middot; ATmega16 &middot; Embedded C &middot; OAR.c</span>\n</header>\n<p class=\"lede\">\n    Three IR proximity sensors look ahead, to the left and to the right. A sensor pulls its pin low when it\n    sees something, so <code>PIND</code> = <code>0b11111111</code> means the way is clear. Each obstacle\n    pattern has its own escape manoeuvre.\n</p>\n\n<main class=\"demo\">\n    <div>\n        <div class=\"panel stage\">\n            <div class=\"toolbar\" id=\"toolbar\">\n                <button class=\"btn\" id=\"clear\">Clear obstacles</button>\n                <button class=\"btn\" id=\"defaults\">Default room</button>\n            </div>\n            <canvas id=\"world\" width=\"1350\" height=\"840\"></canvas>\n            <p class=\"hint\">Click the floor to add a box, drag a box to move it, click a box to remove it.\n                Drag the robot to move it, drag the blue dot to rotate it.</p>\n        </div>\n    </div>\n    <aside>\n        <div class=\"panel\">\n            <h2>Microcontroller I/O</h2>\n            <div id=\"inReg\"></div>\n            <div id=\"outReg\"></div>\n            <h3>Motors</h3>\n            <div id=\"motors\"></div>\n        </div>\n        <div class=\"panel\" id=\"logic\"></div>\n    </aside>\n</main>\n\n<section class=\"explain\">\n    <h2>How it works</h2>\n    <ol>\n        <li>The firmware reads all sensors at once with <code>switch (PIND)</code>; a 0 bit means \"obstacle on this side\".</li>\n        <li>An obstacle on one side only: the robot simply spins away from it until that sensor clears.</li>\n        <li>Anything in front: it reverses for 300 ms, then turns for 300 ms (<code>back_off_and_turn()</code>).</li>\n        <li>Boxed in on all three sides: it spins right for 2 seconds to find a way out.</li>\n        <li>During a manoeuvre the code is inside <code>_delay_ms()</code>, so it does not look at the sensors until the move is finished.</li>\n    </ol>\n    <h2>Try this</h2>\n    <ul>\n        <li>Drive the robot into a corner (drag it there) and watch which case fires.</li>\n        <li>Build a narrow corridor out of boxes and see how the timed manoeuvres cope.</li>\n    </ul>\n</section>\n\n<script src=\"assets/kaizen.js\"></script>\n<script src=\"assets/firmware.js\"></script>\n<script src=\"assets/rigs.js\"></script>\n<script>\n(function () {\n    const K = Kaizen, R = KaizenRigs;\n    const rig = R.obstacleAvoider();\n    const inReg = K.registerView(document.getElementById('inReg'), 'PIND (inputs)', rig.io.labels, '1 = clear, 0 = obstacle detected.');\n    const outReg = K.registerView(document.getElementById('outReg'), 'PORTB (outputs)', K.PORTB_LABELS);\n    const motors = K.motorView(document.getElementById('motors'));\n    const table = K.decisionTable(document.getElementById('logic'), 'Firmware logic &ndash; OAR.c', [\n        { id: 'clear', when: '11111111', meaning: 'Nothing detected', action: 'Forward' },\n        { id: 'right', when: '11111110', meaning: 'Obstacle right', action: 'Spin left' },\n        { id: 'left', when: '11111011', meaning: 'Obstacle left', action: 'Spin right' },\n        { id: 'backLeft', when: '11111101<br>11111100<br>11111010', meaning: 'Centre, centre+right, or left+right', action: 'Reverse 300 ms, spin left 300 ms' },\n        { id: 'backRight', when: '11111001<br>11110101', meaning: 'Centre+left (or centre+PD3)', action: 'Reverse 300 ms, spin right 300 ms' },\n        { id: 'all', when: '11111000', meaning: 'Obstacles on all sides', action: 'Spin right 2 s' },\n    ], K.source('Level 1/Obstacle Avoider Robot/OAR.c'));\n\n    const sim = new K.Sim({\n        canvas: document.getElementById('world'),\n        world: rig.world,\n        robot: rig.robot,\n        tick: t => rig.tick(t),\n        onPointer: K.obstacleEditor(rig.world, { size: 50 }),\n        onFrame: () => {\n            inReg.update(rig.io.PIND());\n            outReg.update(rig.portb);\n            motors.update(rig.robot);\n            table.highlight(rig.trace);\n        },\n    });\n    K.toolbar(document.getElementById('toolbar'), sim, { sound: false, onReset: () => rig.restart() });\n    document.getElementById('clear').onclick = () => { rig.world.obstacles.length = 0; };\n    document.getElementById('defaults').onclick = () => { rig.world.obstacles.splice(0, Infinity, ...R.defaultBoxes()); };\n})();\n</script>\n</body>\n</html>\n", "table-top.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Table Top Robot - Kaizen Robotics live demo</title>\n<link rel=\"stylesheet\" href=\"assets/style.css\">\n</head>\n<body>\n<header class=\"top\">\n    <a class=\"crumb\" href=\"index.html\">&larr; All demos</a>\n    <h1>Table Top Robot</h1>\n    <span class=\"tag\">Level 1 &middot; ATmega16 &middot; Embedded C &middot; TTR.c</span>\n</header>\n<p class=\"lede\">\n    Four downward-facing IR sensors, one at each corner, read 0 while they see the table and 1 once they\n    are past the edge. The robot roams the table and backs away or turns whenever a sensor goes over the edge.\n</p>\n\n<main class=\"demo\">\n    <div>\n        <div class=\"panel stage\">\n            <div class=\"toolbar\" id=\"toolbar\"></div>\n            <canvas id=\"world\" width=\"1350\" height=\"840\"></canvas>\n            <p class=\"hint\">Drag the robot to the edge (or drag the blue dot to aim it off the table) and watch it save itself.\n                S1/S2 are the front sensors, S3/S4 the rear ones.</p>\n        </div>\n    </div>\n    <aside>\n        <div class=\"panel\">\n            <h2>Microcontroller I/O</h2>\n            <div id=\"inReg\"></div>\n            <div id=\"outReg\"></div>\n            <h3>Motors</h3>\n            <div id=\"motors\"></div>\n            <p class=\"hint\" id=\"status\"></p>\n        </div>\n        <div class=\"panel\" id=\"logic\"></div>\n    </aside>\n</main>\n\n<section class=\"explain\">\n    <h2>How it works</h2>\n    <ol>\n        <li>On the table all four sensors read 0, so <code>PIND</code> is <code>0b11110000</code> and the robot drives forward.</li>\n        <li>If a front sensor leaves the table the robot reverses and turns away; if a rear sensor leaves it drives forward and turns.</li>\n        <li>The manoeuvres are timed with <code>_delay_ms()</code>, so the exact distances depend on the motor speed.</li>\n        <li>Patterns that have no <code>case</code> (for example two diagonal sensors off at once) leave the motors doing whatever they did last.</li>\n    </ol>\n</section>\n\n<script src=\"assets/kaizen.js\"></script>\n<script src=\"assets/firmware.js\"></script>\n<script src=\"assets/rigs.js\"></script>\n<script>\n(function () {\n    const K = Kaizen, R = KaizenRigs;\n    const rig = R.tableTop();\n    const inReg = K.registerView(document.getElementById('inReg'), 'PIND (inputs)', rig.io.labels, '0 = sensor sees the table, 1 = past the edge.');\n    const outReg = K.registerView(document.getElementById('outReg'), 'PORTB (outputs)', K.PORTB_LABELS);\n    const motors = K.motorView(document.getElementById('motors'));\n    const status = document.getElementById('status');\n    const table = K.decisionTable(document.getElementById('logic'), 'Firmware logic &ndash; TTR.c', [\n        { id: 'on', when: '11110000', meaning: 'All sensors on the table', action: 'Forward' },\n        { id: 's1', when: '11111000', meaning: 'S1 off', action: 'Reverse 400 ms, spin right 600 ms' },\n        { id: 's2', when: '11110100', meaning: 'S2 off', action: 'Reverse 400 ms, spin left 300 ms' },\n        { id: 's34', when: '11110010<br>11110001', meaning: 'S3 or S4 off', action: 'Forward 200 ms, spin right 300 ms' },\n        { id: 's12', when: '11111100', meaning: 'S1 and S2 off (front edge)', action: 'Reverse 250 ms, spin right 300 ms' },\n        { id: 'rear', when: '11110011', meaning: 'S3 and S4 off (rear edge)', action: 'Forward' },\n        { id: 'spinL', when: '11111001 11110110<br>11111110 11110111', meaning: 'Side off, or only S1 on', action: 'Spin left' },\n        { id: 'spinR', when: '11111011<br>11111101', meaning: 'Only S2 or only S3 on', action: 'Spin right' },\n    ], K.source('Level 1/Table Top Robot/TTR.c'));\n\n    let fellAt = null;\n    const sim = new K.Sim({\n        canvas: document.getElementById('world'),\n        world: rig.world,\n        robot: rig.robot,\n        tick: t => {\n            if (rig.robot.fallen) return;\n            rig.tick(t);\n        },\n        draw: ctx => {\n            // sensor labels\n            ctx.save();\n            ctx.font = 'bold 11px system-ui, sans-serif';\n            ctx.fillStyle = '#fff';\n            for (const s of rig.robot.sensors) {\n                if (s.wx === undefined) continue;\n                ctx.fillText(s.label, s.wx + 6, s.wy - 6);\n            }\n            ctx.restore();\n        },\n        overlay: ctx => {\n            if (!rig.robot.fallen) { fellAt = null; return; }\n            if (fellAt === null) fellAt = performance.now();\n            ctx.save();\n            ctx.fillStyle = 'rgba(0,0,0,0.55)';\n            ctx.fillRect(0, 0, rig.world.width, rig.world.height);\n            ctx.fillStyle = '#fff';\n            ctx.font = 'bold 30px system-ui, sans-serif';\n            ctx.textAlign = 'center';\n            ctx.fillText('Fell off the table!', rig.world.width / 2, rig.world.height / 2);\n            ctx.font = '16px system-ui, sans-serif';\n            ctx.fillText('Restarting in the middle of the table...', rig.world.width / 2, rig.world.height / 2 + 30);\n            ctx.restore();\n            if (performance.now() - fellAt > 2000) rig.restart();\n        },\n        onFrame: () => {\n            inReg.update(rig.io.PIND());\n            outReg.update(rig.portb);\n            motors.update(rig.robot);\n            table.highlight(rig.trace);\n            const off = rig.robot.sensors.filter(s => rig.robot.readings[s.name]).map(s => s.label);\n            status.textContent = off.length ? 'Over the edge: ' + off.join(', ') : 'All sensors on the table';\n        },\n    });\n    K.toolbar(document.getElementById('toolbar'), sim, { sound: false, onReset: () => rig.restart() });\n})();\n</script>\n</body>\n</html>\n", "serial-control.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Serial &amp; Bluetooth Control - Kaizen Robotics live demo</title>\n<link rel=\"stylesheet\" href=\"assets/style.css\">\n<style>\n    .keys { display: grid; grid-template-columns: repeat(5, 54px); gap: 6px; margin: 6px 0 10px; }\n    .keys .btn { padding: 8px 0; font-family: ui-monospace, monospace; font-size: 15px; user-select: none; touch-action: none; }\n    .keys .btn small { display: block; font-family: system-ui, sans-serif; font-size: 10px; color: var(--muted); }\n    .keys .btn.down { background: var(--accent); color: var(--accent-ink); }\n    .keys .btn.down small { color: var(--accent-ink); }\n    #arm { width: 100%; height: auto; border-radius: 8px; border: 1px solid var(--line); }\n</style>\n</head>\n<body>\n<header class=\"top\">\n    <a class=\"crumb\" href=\"index.html\">&larr; All demos</a>\n    <h1>Serial &amp; Bluetooth Controlled Robots</h1>\n    <span class=\"tag\">Level 1 &amp; 2 &middot; UART</span>\n</header>\n<p class=\"lede\">\n    These robots are driven one character at a time over a serial link: a USB-TTL dongle from a PC terminal,\n    or an HC-05 Bluetooth module from a phone app. The firmware waits for a byte, looks it up and sets the motors.\n    The Bluetooth wheelchair also checks an ultrasonic sensor after every command and backs away from obstacles.\n</p>\n\n<main class=\"demo\">\n    <div>\n        <div class=\"panel stage\">\n            <div class=\"toolbar\" id=\"toolbar\">\n                <label class=\"speed\">Firmware <select id=\"fw\"></select></label>\n            </div>\n            <canvas id=\"world\" width=\"1350\" height=\"840\"></canvas>\n            <p class=\"hint\">Click the floor to add a box, click a box to remove it. Drag the robot to move it.</p>\n        </div>\n    </div>\n    <aside>\n        <div class=\"panel\">\n            <h2>Send characters</h2>\n            <div class=\"keys\" id=\"keys\"></div>\n            <label class=\"check\"><input type=\"checkbox\" id=\"hold\"> <span id=\"holdLabel\"></span></label>\n            <h3>Bytes sent (newest last)</h3>\n            <div class=\"serial-log\" id=\"log\"></div>\n            <p class=\"hint\" id=\"uartInfo\"></p>\n        </div>\n        <div class=\"panel\">\n            <h2>Robot</h2>\n            <div id=\"outReg\"></div>\n            <dl class=\"kv\" id=\"pins\"></dl>\n            <h3>Motors</h3>\n            <div id=\"motors\"></div>\n            <div id=\"extra\"></div>\n        </div>\n        <div class=\"panel\" id=\"logic\"></div>\n    </aside>\n</main>\n\n<section class=\"explain\">\n    <h2>How it works</h2>\n    <ol>\n        <li>The UART receives one byte at a time. In <code>TTL.c</code>, <code>uart_receive()</code> blocks until\n            the <code>RXC</code> flag says a byte has arrived, then the <code>switch</code> sets <code>PORTB</code>.</li>\n        <li>The motor pattern stays on until the next byte arrives, so a single key press keeps the robot moving.</li>\n        <li><b>WC.c</b> (wheelchair): after each command it fires a 10 &micro;s trigger pulse at the HC-SR04 and times\n            the echo with Timer1 input capture. Closer than 40 cm means stop for 1 s, then reverse for 1 s. The\n            \"Bluetooth RC Controller\" phone app repeats the key while it is held, which keeps the distance checks going.</li>\n        <li><b>Speed_Control_Assignment.ino</b>: upper-case keys drive at <code>analogWrite(255)</code>, lower-case at 100.</li>\n        <li><b>Computer_Controlled.ino</b>: when no byte is waiting it shows \"Start\" on the LCD and stops everything every\n            50 ms, so the robot only moves while the terminal keeps sending (hold the key down). Keys i/k and j/l move the arm.</li>\n    </ol>\n    <h2>Keyboard</h2>\n    <p>Keys are sent as typed (Shift for upper case). Arrow keys send the forward/back/left/right character of the selected firmware.</p>\n</section>\n\n<script src=\"assets/kaizen.js\"></script>\n<script src=\"assets/firmware.js\"></script>\n<script src=\"assets/rigs.js\"></script>\n<script>\n(function () {\n    const K = Kaizen, R = KaizenRigs;\n    const SOURCES = {\n        TTL: 'Level 1/TTL Dongle (Communication)/TTL.c',\n        WC: 'Level 1/Final Project/Bluetooth-Controlled-WheelChair-with-Obstacle-Avoidance-master/WC.c',\n        SpeedControl: 'Level 2/Assignments/Speed_Control_Assignment/Speed_Control_Assignment.ino',\n        ComputerControlled: 'Level 2/Computer_Controlled/Computer_Controlled.ino',\n    };\n    const KEYS = {\n        TTL: [['F', 'fwd'], ['B', 'back'], ['L', 'left'], ['R', 'right'], ['S', 'stop']],\n        WC: [['F', 'fwd'], ['B', 'back'], ['L', 'left'], ['R', 'right'], ['S', 'stop']],\n        SpeedControl: [['W', 'FAST'], ['S', 'FAST'], ['A', 'FAST'], ['D', 'FAST'], ['x', 'stop'],\n                       ['w', 'slow'], ['s', 'slow'], ['a', 'slow'], ['d', 'slow']],\n        ComputerControlled: [['w', 'fwd'], ['s', 'back'], ['a', 'left'], ['d', 'right'], ['x', 'stop'],\n                             ['i', 'elbow&uarr;'], ['k', 'elbow&darr;'], ['j', 'wrist&uarr;'], ['l', 'wrist&darr;']],\n    };\n    const ARROWS = {\n        TTL: { ArrowUp: 'F', ArrowDown: 'B', ArrowLeft: 'L', ArrowRight: 'R' },\n        WC: { ArrowUp: 'F', ArrowDown: 'B', ArrowLeft: 'L', ArrowRight: 'R' },\n        SpeedControl: { ArrowUp: 'W', ArrowDown: 'S', ArrowLeft: 'A', ArrowRight: 'D' },\n        ComputerControlled: { ArrowUp: 'w', ArrowDown: 's', ArrowLeft: 'a', ArrowRight: 'd' },\n    };\n    const TABLES = {\n        TTL: [\n            { id: 'F', when: \"'F'\", meaning: 'Forward', action: 'PORTB = 0b00001010' },\n            { id: 'B', when: \"'B'\", meaning: 'Backward', action: 'PORTB = 0b00000101' },\n            { id: 'L', when: \"'L'\", meaning: 'Left', action: 'PORTB = 0b00000110' },\n            { id: 'R', when: \"'R'\", meaning: 'Right', action: 'PORTB = 0b00001001' },\n            { id: 'other', when: 'other', meaning: 'Anything else', action: 'PORTB = 0 (stop)' },\n        ],\n        SpeedControl: [\n            { id: 'W', when: \"'W' / 'w'\", meaning: 'Forward', action: 'speed 255 / 100' },\n            { id: 'S', when: \"'S' / 's'\", meaning: 'Reverse', action: 'speed 255 / 100' },\n            { id: 'A', when: \"'A' / 'a'\", meaning: 'Spin left', action: 'speed 255 / 100' },\n            { id: 'D', when: \"'D' / 'd'\", meaning: 'Spin right', action: 'speed 255 / 100' },\n            { id: 'x', when: \"'x'\", meaning: 'Stop', action: 'all motor pins low' },\n        ],\n        ComputerControlled: [\n            { id: 'idle', when: 'no data', meaning: 'Nothing received', action: 'LCD \"Start\", stop all every 50 ms' },\n            { id: 'w', when: \"'w'\", meaning: 'Forward', action: 'drive(1,0,1,0)' },\n            { id: 's', when: \"'s'\", meaning: 'Reverse', action: 'drive(0,1,0,1)' },\n            { id: 'a', when: \"'a'\", meaning: 'Spin left', action: 'drive(0,1,1,0)' },\n            { id: 'd', when: \"'d'\", meaning: 'Spin right', action: 'drive(1,0,0,1)' },\n            { id: 'x', when: \"'x'\", meaning: 'Stop', action: 'stop_all()' },\n            { id: 'i', when: \"'i' / 'k'\", meaning: 'Elbow up / down', action: 'joint(ELBOW)' },\n            { id: 'j', when: \"'j' / 'l'\", meaning: 'Wrist up / down', action: 'joint(WRIST)' },\n        ],\n    };\n    TABLES.WC = TABLES.TTL.map(r => ({ ...r, action: { L: 'PORTB = 0b00001001', R: 'PORTB = 0b00000110' }[r.id] || r.action }))\n        .concat([{ id: 'obstacle', when: '&le; 40 cm', meaning: 'HC-SR04 echo too short', action: 'Stop 1 s, reverse 1 s' }]);\n    const HOLD_DEFAULT = { TTL: false, WC: true, SpeedControl: false, ComputerControlled: true };\n\n    const fwSelect = document.getElementById('fw');\n    for (const [key, fw] of Object.entries(R.SERIAL_FIRMWARE)) fwSelect.append(new Option(fw.label, key));\n    const holdBox = document.getElementById('hold');\n    const extra = document.getElementById('extra');\n    let rig, outReg, table, lcd, armCanvas, held = null, lastSend = -1e9;\n\n    function send(ch) { rig.io.uart.send(ch); }\n\n    function build(name) {\n        const fw = R.SERIAL_FIRMWARE[name];\n        const placed = rig ? rig.world.obstacles : undefined;\n        extra.innerHTML = '';\n        lcd = armCanvas = null;\n        if (fw.arm) {\n            extra.append(K.el('h3', '', 'LCD'));\n            lcd = K.lcd(extra);\n            extra.append(K.el('h3', '', 'Arm (side view)'));\n            armCanvas = K.el('canvas');\n            armCanvas.id = 'arm';\n            armCanvas.width = 340; armCanvas.height = 150;\n            extra.append(armCanvas);\n        }\n        if (fw.sonar) extra.append(K.el('p', 'hint', '<span id=\"sonar\"></span>'));\n        rig = R.serialRobot(name, { obstacles: placed, lcd: lcd || undefined });\n\n        const outBox = document.getElementById('outReg');\n        outBox.innerHTML = '';\n        outReg = fw.level === 1 ? K.registerView(outBox, 'PORTB (outputs)', K.PORTB_LABELS,\n            fw.mirrored ? 'Wheelchair motors are mounted mirrored, so L and R use swapped patterns.' : '') : null;\n        document.getElementById('pins').hidden = fw.level === 1;\n\n        const logic = document.getElementById('logic');\n        logic.innerHTML = '';\n        table = K.decisionTable(logic, 'Firmware logic &ndash; ' + fw.label, TABLES[name], K.source(SOURCES[name]));\n\n        const keys = document.getElementById('keys');\n        keys.innerHTML = '';\n        for (const [ch, label] of KEYS[name]) {\n            const b = K.el('button', 'btn', `${ch}<small>${label}</small>`);\n            b.dataset.ch = ch;\n            b.addEventListener('pointerdown', ev => { ev.preventDefault(); press(ch); });\n            b.addEventListener('pointerup', () => release(ch));\n            b.addEventListener('pointerleave', () => release(ch));\n            keys.append(b);\n        }\n        holdBox.checked = HOLD_DEFAULT[name];\n        document.getElementById('holdLabel').textContent = fw.level === 1\n            ? 'Hold to repeat, like the Android RC app (sends S on release)'\n            : 'Hold to repeat, like keyboard auto-repeat';\n        if (sim) { sim.world = rig.world; sim.robot = rig.robot; }\n    }\n\n    function press(ch) {\n        held = ch;\n        send(ch);\n        lastSend = sim.t;\n        document.querySelectorAll('.keys .btn').forEach(b => b.classList.toggle('down', b.dataset.ch === ch));\n    }\n    function release(ch) {\n        if (held !== ch) return;\n        held = null;\n        document.querySelectorAll('.keys .btn').forEach(b => b.classList.remove('down'));\n        if (holdBox.checked && R.SERIAL_FIRMWARE[fwSelect.value].level === 1) send('S');\n    }\n\n    function drawArm() {\n        const c = armCanvas, ctx = c.getContext('2d'), a = rig.io.jointAngle;\n        ctx.clearRect(0, 0, c.width, c.height);\n        ctx.fillStyle = '#64748b';\n        ctx.fillRect(40, 120, 90, 18);\n        const base = [85, 120];\n        const e = -0.2 - a.elbow * 1.2, len1 = 90;\n        const p1 = [base[0] + Math.cos(e) * len1, base[1] + Math.sin(e) * len1];\n        const w = e + 0.6 - a.wrist * 1.6, len2 = 70;\n        const p2 = [p1[0] + Math.cos(w) * len2, p1[1] + Math.sin(w) * len2];\n        ctx.lineCap = 'round';\n        ctx.strokeStyle = '#1f7a4d'; ctx.lineWidth = 12;\n        ctx.beginPath(); ctx.moveTo(...base); ctx.lineTo(...p1); ctx.stroke();\n        ctx.strokeStyle = '#2563eb'; ctx.lineWidth = 9;\n        ctx.beginPath(); ctx.moveTo(...p1); ctx.lineTo(...p2); ctx.stroke();\n        ctx.fillStyle = '#111';\n        for (const p of [base, p1]) { ctx.beginPath(); ctx.arc(p[0], p[1], 6, 0, Math.PI * 2); ctx.fill(); }\n        ctx.font = '12px system-ui, sans-serif';\n        ctx.fillStyle = '#64748b';\n        ctx.fillText(`elbow ${(a.elbow * 100).toFixed(0)}%   wrist ${(a.wrist * 100).toFixed(0)}%`, 160, 140);\n    }\n\n    let sim = null;\n    const initial = new URLSearchParams(location.search).get('fw');\n    if (R.SERIAL_FIRMWARE[initial]) fwSelect.value = initial;\n    build(fwSelect.value);\n    const motors = K.motorView(document.getElementById('motors'));\n    sim = new K.Sim({\n        canvas: document.getElementById('world'),\n        world: rig.world,\n        robot: rig.robot,\n        tick: t => {\n            if (held && holdBox.checked && t - lastSend >= 50) { send(held); lastSend = t; }\n            rig.tick(t);\n        },\n        onPointer: (type, x, y) => K.obstacleEditor(rig.world, { size: 50 })(type, x, y),\n        draw: ctx => {\n            const s = rig.robot.sensors[0];\n            if (!s || s.wx === undefined) return;\n            // 40 cm stop distance marker\n            ctx.save();\n            ctx.strokeStyle = 'rgba(220,38,38,0.6)';\n            ctx.setLineDash([5, 5]);\n            ctx.beginPath();\n            ctx.arc(s.wx, s.wy, 40 * R.PX_PER_CM, rig.robot.heading - 0.5, rig.robot.heading + 0.5);\n            ctx.stroke();\n            ctx.restore();\n        },\n        onFrame: () => {\n            const fw = R.SERIAL_FIRMWARE[fwSelect.value];\n            if (outReg) outReg.update(rig.portb);\n            else {\n                const j = rig.io.joints;\n                document.getElementById('pins').innerHTML =\n                    `<dt>Left motor</dt><dd>${rig.robot.target.left.toFixed(2)}</dd><dt>Right motor</dt><dd>${rig.robot.target.right.toFixed(2)}</dd>` +\n                    (fw.arm ? `<dt>Elbow motor</dt><dd>${j.elbow}</dd><dt>Wrist motor</dt><dd>${j.wrist}</dd>` : '');\n            }\n            motors.update(rig.robot);\n            table.highlight(rig.trace);\n            const log = rig.io.uart.log;\n            document.getElementById('log').textContent = log.slice(-40).join(' ');\n            document.getElementById('uartInfo').textContent =\n                `Receive buffer: ${rig.io.uart.available()}/${rig.io.uart.depth} bytes` +\n                (rig.io.uart.dropped ? `, ${rig.io.uart.dropped} dropped (overrun)` : '');\n            const sonar = document.getElementById('sonar');\n            if (sonar) {\n                const cm = rig.io.sonarCm();\n                sonar.textContent = 'HC-SR04 distance: ' + (cm === 0xffff ? 'no echo (> 4 m)' : cm + ' cm') + ' (stops at 40 cm)';\n            }\n            if (armCanvas) drawArm();\n        },\n    });\n    K.toolbar(document.getElementById('toolbar'), sim, { sound: false, onReset: () => rig.restart() });\n    fwSelect.onchange = () => build(fwSelect.value);\n\n    const keyChar = ev => ARROWS[fwSelect.value][ev.key] || (ev.key.length === 1 ? ev.key : null);\n    addEventListener('keydown', ev => {\n        if (ev.target.matches('select, input[type=text], input[type=number]') || ev.repeat) return;\n        const ch = keyChar(ev);\n        if (!ch) return;\n        if (ev.key.startsWith('Arrow')) ev.preventDefault();\n        press(ch);\n    });\n    addEventListener('keyup', ev => {\n        const ch = keyChar(ev);\n        if (ch && held && ch.toLowerCase() === held.toLowerCase()) release(held);\n    });\n})();\n</script>\n</body>\n</html>\n", "gesture.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Gesture &amp; Wireless Control - Kaizen Robotics live demo</title>\n<link rel=\"stylesheet\" href=\"assets/style.css\">\n<style>\n    #pad { width: 100%; max-width: 340px; height: auto; border-radius: 8px; border: 1px solid var(--line); touch-action: none; cursor: grab; }\n    .switch { display: grid; grid-template-columns: 110px repeat(3, 1fr); gap: 4px; align-items: center; margin: 4px 0; font-size: 13px; }\n    .switch .btn { padding: 4px 0; font-size: 13px; }\n    .switch .btn.active { background: var(--accent); color: var(--accent-ink); outline: none; }\n    .link { display: flex; gap: 10px; align-items: center; font-size: 13px; color: var(--muted); }\n    .big-cmd { font: 700 34px/1 ui-monospace, monospace; min-width: 44px; text-align: center; padding: 6px; border-radius: 8px; background: var(--code); }\n</style>\n</head>\n<body>\n<header class=\"top\">\n    <a class=\"crumb\" href=\"index.html\">&larr; All demos</a>\n    <h1>Gesture &amp; Wireless Remote Control</h1>\n    <span class=\"tag\">Level 2 &middot; Arduino &middot; MEMS accelerometer</span>\n</header>\n<p class=\"lede\">\n    Two microcontrollers work together. The <b>remote</b> reads a MEMS accelerometer (or switches) and sends\n    one-letter commands over a wireless serial link. The <b>robot</b> receives each letter and drives its motors.\n    Drag the dot on the tilt pad to tilt the virtual accelerometer.\n</p>\n\n<main class=\"demo\">\n    <div>\n        <div class=\"panel stage\">\n            <div class=\"toolbar\" id=\"toolbar\">\n                <label class=\"speed\">Remote <select id=\"remote\"></select></label>\n            </div>\n            <canvas id=\"world\" width=\"1350\" height=\"840\"></canvas>\n            <p class=\"hint\" id=\"hint\">Drag the robot to move it, drag the blue dot to rotate it.</p>\n        </div>\n    </div>\n    <aside>\n        <div class=\"panel\">\n            <h2>Remote (transmitter)</h2>\n            <div id=\"tiltBox\">\n                <canvas id=\"pad\" width=\"340\" height=\"340\"></canvas>\n                <dl class=\"kv\" style=\"margin-top:6px\">\n                    <dt>analogRead(A0) x</dt><dd id=\"ax\"></dd>\n                    <dt>analogRead(A1) y</dt><dd id=\"ay\"></dd>\n                </dl>\n                <p class=\"hint\">Coloured bands are the tilt windows from the sketch. Where they overlap, the later\n                    <code>if</code> in the code wins. <button class=\"btn\" id=\"level\">Hold level</button></p>\n            </div>\n            <div id=\"switches\"></div>\n            <h3>Wireless link</h3>\n            <div class=\"link\"><span>Last sent</span><span class=\"big-cmd\" id=\"cmd\">&ndash;</span><span id=\"linkInfo\"></span></div>\n            <div class=\"serial-log\" id=\"log\" style=\"margin-top:6px\"></div>\n        </div>\n        <div class=\"panel\">\n            <h2>Robot (receiver)</h2>\n            <div id=\"motors\"></div>\n            <div id=\"armBox\"></div>\n        </div>\n        <div class=\"panel\" id=\"logic\"></div>\n    </aside>\n</main>\n\n<section class=\"explain\">\n    <h2>How it works</h2>\n    <ol>\n        <li>The accelerometer outputs a voltage per axis that changes as it tilts. <code>analogRead()</code> turns\n            it into a number from 0 to 1023; level is about 400 on each axis.</li>\n        <li>The remote checks the reading against a window for each command (for example <code>y</code> between 415 and 475\n            means \"reverse\") and sends that letter with <code>Serial.print()</code> at 9600 baud.</li>\n        <li>The receiver waits for <code>Serial.available()</code>, reads the letter and sets the motor driver pins.</li>\n        <li>The pick and place version adds two DPDT switches on the remote. They drive the lift motor\n            (<code>z</code>/<code>y</code>) and the gripper motor (<code>x</code>/<code>w</code>) on the robot's arm.</li>\n    </ol>\n    <h2>Try this</h2>\n    <ul>\n        <li>With <b>Level2_Remote.ino</b>, try to find the forward window: it is only 8 ADC counts tall\n            (<code>380&ndash;388</code>), so the remote has to be held very precisely. This is why the window values were re-calibrated\n            for the gesture bot remote.</li>\n        <li>With the pick and place remote, drive to the orange block, lower the lift, close the gripper, carry the\n            block to the drop zone and open the gripper.</li>\n    </ul>\n</section>\n\n<script src=\"assets/kaizen.js\"></script>\n<script src=\"assets/firmware.js\"></script>\n<script src=\"assets/rigs.js\"></script>\n<script>\n(function () {\n    const K = Kaizen, R = KaizenRigs;\n    const SOURCES = {\n        RFRemote: 'Level 2/RF Control/Level2_Remote.ino',\n        GestureRemote: 'Level 2/Gesture Bot/Level2_Remote2/Level2_Remote2.ino',\n        ArmRemote: 'Level 2/Assignments/Assignment_Arm_Remote/Assignment_Arm_Remote.ino',\n        DPDTRemote: 'Level 2/Assignments/Assignment_DPDT_Wireless/Assignment_DPDT_Wireless.ino',\n        receiver: 'Level 2/Assignments/Assignment_Gesture2/Assignment_Gesture2.ino',\n    };\n    const COLORS = { s: '#64748b', f: '#16a34a', R: '#dc2626', o: '#dc2626', l: '#2563eb', r: '#9333ea' };\n    const NAMES = { s: 'stop', f: 'forward', R: 'reverse', o: 'reverse', l: 'left', r: 'right', z: 'lift up', y: 'lift down', x: 'gripper open', w: 'gripper close' };\n    const RX_TABLE = [\n        { id: 'f', when: \"'f'\", meaning: 'Forward', action: 'drive(1,0,1,0)' },\n        { id: 's', when: \"'s'\", meaning: 'Stop', action: 'drive(0,0,0,0)' },\n        { id: 'R', when: \"'R'\", meaning: 'Reverse', action: 'drive(0,1,0,1)' },\n        { id: 'l', when: \"'l'\", meaning: 'Left', action: 'drive(0,1,1,0)' },\n        { id: 'r', when: \"'r'\", meaning: 'Right', action: 'drive(1,0,0,1)' },\n        { id: 'z', when: \"'z' / 'y'\", meaning: 'Arm motor 1 (lift)', action: 'up / down' },\n        { id: 'x', when: \"'x' / 'w'\", meaning: 'Arm motor 2 (gripper)', action: 'open / close' },\n    ];\n    const RX2_TABLE = RX_TABLE.slice(0, 5).map(r => (r.id === 'R' ? { ...r, id: 'o', when: \"'o'\" } : r));\n\n    const sel = document.getElementById('remote');\n    for (const [key, rm] of Object.entries(R.REMOTES)) sel.append(new Option(rm.label, key));\n    const pad = document.getElementById('pad');\n    const pctx = pad.getContext('2d');\n    const LO = 280, HI = 540;\n    let rig, table, block, sim = null;\n\n    const toPad = v => (v - LO) / (HI - LO) * pad.width;\n    const fromPad = p => LO + p / pad.width * (HI - LO);\n\n    function switchRow(box, name, label, opts) {\n        const row = K.el('div', 'switch', `<span>${label}</span>`);\n        for (const [val, text] of opts) {\n            const b = K.el('button', 'btn' + (val === 0 ? ' active' : ''), text);\n            b.onclick = () => {\n                rig.remoteIo.switches[name] = val;\n                row.querySelectorAll('.btn').forEach(x => x.classList.toggle('active', x === b));\n            };\n            row.append(b);\n        }\n        box.append(row);\n    }\n\n    function build(name) {\n        rig = R.gesture(name);\n        const rm = rig.rm;\n        block = { x: 520, y: 400, r: 11, carried: false };\n        document.getElementById('tiltBox').hidden = !rm.tilt;\n        const sw = document.getElementById('switches');\n        sw.innerHTML = '';\n        if (name === 'DPDTRemote') {\n            switchRow(sw, 'drive', 'Drive switch', [[1, 'forward'], [0, 'off'], [-1, 'reverse']]);\n            switchRow(sw, 'steer', 'Steer switch', [[-1, 'left'], [0, 'off'], [1, 'right']]);\n        }\n        if (rm.arm) {\n            switchRow(sw, 'arm1', 'Arm 1 (lift)', [[1, 'up (z)'], [0, 'off'], [-1, 'down (y)']]);\n            switchRow(sw, 'arm2', 'Arm 2 (gripper)', [[1, 'open (x)'], [0, 'off'], [-1, 'close (w)']]);\n        }\n        const logic = document.getElementById('logic');\n        logic.innerHTML = '';\n        const rows = name === 'GestureRemote' ? RX2_TABLE : rm.arm ? RX_TABLE : RX_TABLE.slice(0, 5);\n        table = K.decisionTable(logic, 'Receiver logic &ndash; ' + rm.receiverLabel, rows,\n            name === 'GestureRemote' ? null : K.source(SOURCES.receiver));\n        logic.append(K.el('p', 'hint', `Transmitter: <a href=\"${K.source(SOURCES[name])}\" target=\"_blank\" rel=\"noopener\">${rm.label}</a>`));\n        document.getElementById('armBox').innerHTML = rm.arm ? '<h3>Arm</h3><dl class=\"kv\" id=\"armKv\"></dl>' : '';\n        if (sim) { sim.world = rig.world; sim.robot = rig.robot; }\n    }\n\n    function drawPad() {\n        const rm = rig.rm, w = rm.program.windows, W = pad.width;\n        pctx.clearRect(0, 0, W, W);\n        pctx.fillStyle = getComputedStyle(document.body).getPropertyValue('--code');\n        pctx.fillRect(0, 0, W, W);\n        for (const win of w) {\n            const x0 = win.x ? toPad(win.x[0]) : 0, x1 = win.x ? toPad(win.x[1]) : W;\n            const y0 = win.y ? toPad(win.y[0]) : 0, y1 = win.y ? toPad(win.y[1]) : W;\n            pctx.fillStyle = COLORS[win.c] + '33';\n            pctx.strokeStyle = COLORS[win.c];\n            pctx.fillRect(x0, y0, x1 - x0, y1 - y0);\n            pctx.strokeRect(x0, y0, x1 - x0, y1 - y0);\n            pctx.fillStyle = COLORS[win.c];\n            pctx.font = 'bold 13px ui-monospace, monospace';\n            pctx.fillText(`'${win.c}'`, x0 + 4, y0 + 14);\n        }\n        pctx.fillStyle = '#94a3b8';\n        pctx.font = '11px system-ui, sans-serif';\n        for (let v = 300; v <= 520; v += 50) {\n            pctx.fillText(v, toPad(v) - 8, W - 4);\n            pctx.fillText(v, 2, toPad(v) + 4);\n        }\n        const t = rig.remoteIo.tilt;\n        pctx.fillStyle = '#111';\n        pctx.strokeStyle = '#fff';\n        pctx.lineWidth = 2;\n        pctx.beginPath(); pctx.arc(toPad(t.x), toPad(t.y), 8, 0, Math.PI * 2); pctx.fill(); pctx.stroke();\n    }\n\n    let padDrag = false;\n    const padMove = ev => {\n        const r = pad.getBoundingClientRect();\n        const px = (ev.clientX - r.left) / r.width * pad.width, py = (ev.clientY - r.top) / r.height * pad.height;\n        rig.remoteIo.tilt = { x: Math.max(LO, Math.min(HI, fromPad(px))), y: Math.max(LO, Math.min(HI, fromPad(py))) };\n    };\n    pad.addEventListener('pointerdown', ev => { padDrag = true; pad.setPointerCapture(ev.pointerId); padMove(ev); });\n    pad.addEventListener('pointermove', ev => padDrag && padMove(ev));\n    pad.addEventListener('pointerup', () => { padDrag = false; });\n    document.getElementById('level').onclick = () => { rig.remoteIo.tilt = { ...rig.rm.program.rest }; };\n\n    // Pick and place: block follows the gripper while it is closed around it\n    function updateBlock() {\n        const rb = rig.robot, a = rig.io.jointAngle;\n        const [fx, fy] = rb.toWorld(40, 0);\n        if (!block.carried && a.arm1 < 0.3 && a.arm2 < 0.3 && Math.hypot(fx - block.x, fy - block.y) < 18) block.carried = true;\n        if (block.carried && a.arm2 > 0.5) block.carried = false;\n        if (block.carried) { block.x = fx; block.y = fy; }\n    }\n\n    const initial = new URLSearchParams(location.search).get('fw');\n    if (R.REMOTES[initial]) sel.value = initial;\n    build(sel.value);\n    const motors = K.motorView(document.getElementById('motors'));\n    sim = new K.Sim({\n        canvas: document.getElementById('world'),\n        world: rig.world,\n        robot: rig.robot,\n        tick: t => { rig.tick(t); if (rig.rm.arm) updateBlock(); },\n        draw: ctx => {\n            if (!rig.rm.arm) return;\n            const rb = rig.robot, a = rig.io.jointAngle;\n            ctx.save();\n            // arm reaching forward from the robot\n            const [ax, ay] = rb.toWorld(18, 0), [fx, fy] = rb.toWorld(40, 0);\n            ctx.strokeStyle = '#475569'; ctx.lineWidth = 6; ctx.lineCap = 'round';\n            ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(fx, fy); ctx.stroke();\n            const open = 4 + a.arm2 * 10;\n            for (const side of [-1, 1]) {\n                const [gx, gy] = rb.toWorld(40, side * open), [hx, hy] = rb.toWorld(52, side * open);\n                ctx.lineWidth = 3;\n                ctx.beginPath(); ctx.moveTo(gx, gy); ctx.lineTo(hx, hy); ctx.stroke();\n            }\n            const lift = block.carried ? 1 + a.arm1 * 0.5 : 1;\n            ctx.fillStyle = 'rgba(0,0,0,0.15)';\n            ctx.beginPath(); ctx.arc(block.x + 3 * lift, block.y + 3 * lift, block.r, 0, Math.PI * 2); ctx.fill();\n            ctx.fillStyle = '#ea580c'; ctx.strokeStyle = '#9a3412'; ctx.lineWidth = 2;\n            ctx.beginPath(); ctx.arc(block.x, block.y, block.r * lift, 0, Math.PI * 2); ctx.fill(); ctx.stroke();\n            ctx.restore();\n        },\n        onFrame: () => {\n            const rm = rig.rm, t = rig.remoteIo.tilt;\n            if (rm.tilt) {\n                drawPad();\n                document.getElementById('ax').textContent = Math.round(t.x);\n                document.getElementById('ay').textContent = Math.round(t.y);\n            }\n            const log = rig.link.log;\n            const last = log[log.length - 1];\n            document.getElementById('cmd').textContent = last || '\u2013';\n            document.getElementById('cmd').title = NAMES[last] || '';\n            document.getElementById('log').textContent = log.slice(-36).join('');\n            document.getElementById('linkInfo').textContent = last ? '= ' + (NAMES[last] || '?') : 'nothing sent';\n            motors.update(rig.robot);\n            table.highlight(rig.trace === 'y' ? 'z' : rig.trace === 'w' ? 'x' : rig.trace);\n            const kv = document.getElementById('armKv');\n            if (kv) {\n                const a = rig.io.jointAngle;\n                kv.innerHTML = `<dt>Lift</dt><dd>${Math.round(a.arm1 * 100)}%</dd><dt>Gripper opening</dt><dd>${Math.round(a.arm2 * 100)}%</dd>` +\n                    `<dt>Block</dt><dd>${block.carried ? 'held' : 'on the floor'}</dd>`;\n            }\n        },\n    });\n    K.toolbar(document.getElementById('toolbar'), sim, { sound: false, onReset: () => build(sel.value) });\n    sel.onchange = () => build(sel.value);\n})();\n</script>\n</body>\n</html>\n", "maze.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Maze Solver - Kaizen Robotics live demo</title>\n<link rel=\"stylesheet\" href=\"assets/style.css\">\n<style>\n    .sensors5 { display: grid; grid-template-columns: 70px repeat(5, 34px); gap: 4px; align-items: center; font-size: 13px; margin: 3px 0; }\n    .sensors5 .s { text-align: center; border-radius: 6px; border: 1px solid var(--line); font: 700 15px/26px ui-monospace, monospace; }\n    .sensors5 .s.black { background: #111; color: #fff; border-color: #111; }\n    .sensors5 .h { text-align: center; font-size: 11px; color: var(--muted); }\n    .phase { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 8px; }\n    .phase span { font-size: 12px; padding: 3px 9px; border-radius: 99px; background: var(--code); color: var(--muted); }\n    .phase span.now { background: var(--accent); color: var(--accent-ink); }\n    #event { font-weight: 600; min-height: 1.5em; }\n    #steps { font-family: ui-monospace, monospace; font-size: 13px; max-height: 150px; overflow: auto; }\n    #steps div.cur { background: var(--hl); color: var(--hl-ink); }\n</style>\n</head>\n<body>\n<header class=\"top\">\n    <a class=\"crumb\" href=\"index.html\">&larr; All demos</a>\n    <h1>Maze Solving Robot</h1>\n    <span class=\"tag\">Level 2 &middot; Arduino &middot; 5 line sensors &middot; left hand rule</span>\n</header>\n<p class=\"lede\">\n    The robot explores a black-line maze by always preferring the leftmost way. It notes every decision at a\n    junction (<b>L</b>, <b>S</b>, <b>R</b>) and every dead-end U-turn (<b>U</b>). The shortest-path version then removes each\n    detour from that list and drives the maze again without a single wrong turn. The return version drives back to the start.\n</p>\n\n<main class=\"demo\">\n    <div>\n        <div class=\"panel stage\">\n            <div class=\"toolbar\" id=\"toolbar\">\n                <label class=\"speed\">Sketch <select id=\"mode\">\n                    <option value=\"explore\">maze_solver.ino &ndash; explore only</option>\n                    <option value=\"replay\" selected>ShortestPathAlgorithm.ino &ndash; explore, then shortest run</option>\n                    <option value=\"return\">Maze_bot_return_final.ino &ndash; explore, then drive back</option>\n                </select></label>\n                <button class=\"btn primary\" id=\"run\">Run</button>\n                <button class=\"btn\" id=\"step\">Step</button>\n                <button class=\"btn\" id=\"reset\">Reset</button>\n                <button class=\"btn\" id=\"newMaze\">New maze</button>\n                <label class=\"speed\">Speed <select id=\"speed\"><option>0.5</option><option selected>1</option><option>2</option><option>4</option></select>&times;</label>\n            </div>\n            <canvas id=\"world\" width=\"1350\" height=\"900\"></canvas>\n            <p class=\"hint\">Green circle: start (a dead end). Black square: end box. The dashed trail is where the robot has driven.</p>\n        </div>\n    </div>\n    <aside>\n        <div class=\"panel\">\n            <div class=\"phase\" id=\"phase\"></div>\n            <div id=\"event\"></div>\n            <h3>Sensors at this node (0 = black line)</h3>\n            <div class=\"sensors5\"><span></span><span class=\"h\">L</span><span class=\"h\">C1</span><span class=\"h\">C2</span><span class=\"h\">C3</span><span class=\"h\">R</span></div>\n            <div class=\"sensors5\" id=\"before\"></div>\n            <div class=\"sensors5\" id=\"after\"></div>\n            <h3>LCD</h3>\n            <div id=\"lcd\"></div>\n        </div>\n        <div class=\"panel\">\n            <h2 id=\"pathTitle\">Recorded path</h2>\n            <div class=\"chips\" id=\"path\"></div>\n            <div id=\"simplify\" hidden>\n                <h3>Simplification steps</h3>\n                <div id=\"steps\"></div>\n            </div>\n            <p class=\"hint\" id=\"pathNote\"></p>\n        </div>\n    </aside>\n</main>\n\n<section class=\"explain\">\n    <h2>What the sensors see</h2>\n    <p>Five sensors in a row read 0 over the black line. At every node the sketch first reads the pattern, then\n        <code>inch()</code>es forward 0.3&ndash;0.5 s and reads again to see whether the line continues straight ahead:</p>\n    <pre>pattern  after inch   meaning              left hand rule   recorded\n11011    -            straight line        forward          -\n11111    -            dead end             U-turn           U\n11000    11111        right turn only      right            -\n11000    11011        straight or right    straight         S\n00011    11111        left turn only       left             -\n00011    11011        straight or left     left             L\n00000    11111        T junction           left             L\n00000    11011        4-way crossing       left             L\n00000    00000        end box              stop             E</pre>\n    <h2>Shortest path: removing detours</h2>\n    <p>Every <b>U</b> marks a dead end. The three letters around it (turn in, U-turn, turn out) all happen at one\n        junction, so they can be replaced by the single turn the robot should have made there. Treating turns as angles\n        (S = 0&deg;, R = 90&deg;, U = 180&deg;, L = 270&deg;) the replacement is simply their sum:</p>\n    <pre>L U L  -> 270+180+270 = 720 = 0   -> S\nL U S  -> 270+180+0   = 450 = 90  -> R\nS U L  ->   0+180+270 = 450 = 90  -> R\nL U R  -> 270+180+90  = 540 = 180 -> U\nS U S  ->   0+180+0   = 180       -> U\nR U L  ->  90+180+270 = 540 = 180 -> U</pre>\n    <p><code>simplify_path()</code> applies this while it reads the path, so nested detours collapse too. On the\n        shortest run the robot follows the line as usual; at each junction that offers a choice it takes the next\n        letter. For the return trip <code>reverse_path()</code> reverses the list and swaps L and R, because a left turn on\n        the way in is a right turn on the way back.</p>\n</section>\n\n<script src=\"assets/kaizen.js\"></script>\n<script src=\"assets/firmware.js\"></script>\n<script src=\"assets/maze.js\"></script>\n<script>\n(function () {\n    const K = Kaizen, M = KaizenMaze;\n    const W = 7, H = 5, CELL = 120, OX = 90, OY = 60;\n    const canvas = document.getElementById('world');\n    const ctx = canvas.getContext('2d');\n    const WORLD_W = 900, WORLD_H = 600;\n    const lcd = K.lcd(document.getElementById('lcd'));\n    const modeSel = document.getElementById('mode');\n    const runBtn = document.getElementById('run');\n    const speedSel = document.getElementById('speed');\n    const PHASES = { explore: ['Explore'], replay: ['Explore', 'Simplify', 'Shortest run'], return: ['Explore', 'Simplify', 'Drive back'] };\n\n    const robot = new K.Robot({\n        sensors: [-22, -11, 0, 11, 22].map((dy, i) => ({ name: 's' + i, type: 'line', dx: 30, dy })),\n        style: { body: '#1f7a4d', trail: 'rgba(37,99,235,0.45)' },\n    });\n\n    let seed = 8, maze, state;\n    const node = (x, y) => [OX + x * CELL, OY + y * CELL];\n    const dirAngle = d => [0, Math.PI / 2, Math.PI, -Math.PI / 2][d];\n\n    function reset() {\n        maze = M.generate(W, H, seed);\n        const [sx, sy] = node(maze.start.x, maze.start.y);\n        robot.reset({ x: sx, y: sy, heading: dirAngle(maze.start.dir) });\n        robot.trail = [];\n        state = {\n            phase: 'explore', gen: M.run(maze, 'explore'), anim: null, running: false,\n            path: [], plan: [], planIndex: -1, steps: [], stepIndex: -1, arrivalDir: 0,\n        };\n        lcd.show('MSR with LHR');\n        setEvent(null);\n        runBtn.textContent = 'Run';\n        render();\n        renderPanel();\n    }\n\n    function setEvent(ev) {\n        const box = document.getElementById('event');\n        const rows = [document.getElementById('before'), document.getElementById('after')];\n        rows.forEach(r => (r.innerHTML = ''));\n        robot.readings = {};\n        if (!ev) { box.textContent = 'Press Run or Step to start.'; return; }\n        let text = M.KIND_LABEL[ev.kind] || ({ start: 'Start', uturnAtEnd: 'Turn around in the end box', home: 'Back at the start: stop' })[ev.kind] || ev.kind;\n        if (ev.recorded) text += ` \u2192 record '${ev.recorded}'`;\n        if (ev.decision) text += ` \u2192 take '${ev.decision}' from the path`;\n        box.textContent = text;\n        const draw = (row, label, pat) => {\n            if (!pat) return;\n            row.append(K.el('span', '', label));\n            for (const b of pat) row.append(K.el('span', 's' + (b === '0' ? ' black' : ''), b));\n        };\n        draw(rows[0], 'reading', ev.before);\n        draw(rows[1], 'after inch', ev.after);\n        if (ev.before) [...ev.before].forEach((b, i) => (robot.readings['s' + i] = b === '0' ? 1 : 0));\n        if (ev.lcd) lcd.show(ev.lcd[0], ev.lcd[1] || '');\n    }\n\n    function renderPanel() {\n        const phases = PHASES[modeSel.value];\n        const cur = { explore: 0, simplify: 1, replay: 2, return: 2, done: phases.length }[state.phase];\n        document.getElementById('phase').innerHTML = phases.map((p, i) => `<span class=\"${i === cur ? 'now' : ''}\">${i + 1}. ${p}</span>`).join('');\n        const pathBox = document.getElementById('path');\n        const showPlan = state.phase === 'replay' || state.phase === 'return' || (state.phase === 'done' && state.plan.length);\n        const list = showPlan ? state.plan : state.path;\n        document.getElementById('pathTitle').textContent = showPlan\n            ? (modeSel.value === 'return' ? 'Return path (reversed, L\u2194R swapped)' : 'Shortest path')\n            : 'Recorded path';\n        pathBox.innerHTML = list.length ? list.map((c, i) => `<span class=\"chip${showPlan && i < state.planIndex ? ' done' : ''}${showPlan && i === state.planIndex ? ' cur' : ''}\">${c}</span>`).join('') : '<span class=\"hint\">(empty)</span>';\n        const simp = document.getElementById('simplify');\n        simp.hidden = !state.steps.length;\n        document.getElementById('steps').innerHTML = state.steps.map((s, i) =>\n            `<div class=\"${i === state.stepIndex ? 'cur' : ''}\">${i < state.stepIndex + 1 || state.phase !== 'simplify' ? `${s.before}: ${s.from} \u2192 ${s.to}` : '&hellip;'}</div>`).join('');\n        const n = state.path.filter(c => c !== 'E').length;\n        document.getElementById('pathNote').textContent = n > 29 ? 'Warning: longer than the sketch\u2019s 30-character path buffer.' :\n            state.phase === 'done' && modeSel.value !== 'explore'\n                ? `Explored with ${n} recorded moves; the shortest route needs ${state.plan.length} junction decisions (${maze.shortest} nodes).`\n                : '';\n    }\n\n    // ---------------------------------------------------------- animation\n\n    function beginEvent(ev) {\n        setEvent(ev);\n        const [x, y] = node(ev.x, ev.y);\n        robot.x = x; robot.y = y;\n        const turn = ev.turn || (ev.kind === 'uturnAtEnd' ? 'U' : 'S');\n        const delta = { L: -Math.PI / 2, R: Math.PI / 2, U: -Math.PI, S: 0 }[turn] || 0;\n        state.anim = { ev, t: 0, h0: robot.heading, h1: robot.heading + delta, from: [x, y],\n                       to: ev.done ? null : node(ev.x + M.DX[ev.newDir], ev.y + M.DY[ev.newDir]),\n                       pause: ev.before ? 0.45 : 0.1, turnT: delta ? 0.45 : 0, moveT: 0.55 };\n        if (ev.recorded) state.path.push(ev.recorded);\n        if (ev.kind === 'end' && state.phase === 'explore') state.path.push('E');\n        if (ev.decision) state.planIndex++;\n        renderPanel();\n    }\n\n    function finishEvent() {\n        const ev = state.anim.ev;\n        state.anim = null;\n        if (!ev.done) return;\n        if (state.phase === 'explore') {\n            state.arrivalDir = ev.dir;\n            if (modeSel.value === 'explore') return finish();\n            const s = M.simplify(state.path);\n            state.steps = s.steps;\n            state.plan = modeSel.value === 'return' ? M.reverse(s.path) : s.path;\n            state.simplified = s.path;\n            state.phase = 'simplify';\n            state.stepIndex = -1;\n            state.simplifyT = 0;\n            lcd.show('ENTERED', 'REPLACEMENT');\n        } else {\n            finish();\n        }\n        renderPanel();\n    }\n\n    function startRun() {\n        state.phase = modeSel.value === 'return' ? 'return' : 'replay';\n        state.planIndex = -1;\n        robot.trail = [];\n        if (state.phase === 'replay') {\n            const [sx, sy] = node(maze.start.x, maze.start.y);\n            Object.assign(robot, { x: sx, y: sy, heading: dirAngle(maze.start.dir) });\n            lcd.show('FINAL=', state.plan.join(''));\n        }\n        state.gen = M.run(maze, state.phase, { path: state.plan, arrivalDir: state.arrivalDir });\n        renderPanel();\n    }\n\n    function finish() {\n        state.phase = 'done';\n        state.running = false;\n        runBtn.textContent = 'Run';\n        renderPanel();\n    }\n\n    // Advances the animation by dt seconds; returns false when idle\n    function advance(dt) {\n        if (state.phase === 'done') return false;\n        if (state.phase === 'simplify') {\n            state.simplifyT += dt;\n            if (state.simplifyT < 0.9) return true;\n            state.simplifyT = 0;\n            if (state.stepIndex < state.steps.length - 1) {\n                state.stepIndex++;\n                const s = state.steps[state.stepIndex];\n                lcd.show(`${s.from} -> ${s.to}`, s.before.slice(0, 16));\n            } else {\n                lcd.show('FINAL=', state.plan.join('').slice(0, 16));\n                startRun();\n            }\n            renderPanel();\n            return true;\n        }\n        if (!state.anim) {\n            const r = state.gen.next();\n            if (r.done) { finish(); return false; }\n            beginEvent(r.value);\n            return true;\n        }\n        const a = state.anim;\n        a.t += dt;\n        let t = a.t;\n        if (t < a.pause) return true;\n        t -= a.pause;\n        if (t < a.turnT) {\n            robot.heading = a.h0 + (a.h1 - a.h0) * (t / a.turnT);\n            return true;\n        }\n        robot.heading = a.h1;\n        t -= a.turnT;\n        if (a.to && t < a.moveT) {\n            const k = t / a.moveT;\n            robot.x = a.from[0] + (a.to[0] - a.from[0]) * k;\n            robot.y = a.from[1] + (a.to[1] - a.from[1]) * k;\n            pushTrail();\n            return true;\n        }\n        if (a.to) { robot.x = a.to[0]; robot.y = a.to[1]; pushTrail(); }\n        finishEvent();\n        return true;\n    }\n\n    function pushTrail() {\n        const last = robot.trail[robot.trail.length - 1];\n        if (!last || Math.hypot(last[0] - robot.x, last[1] - robot.y) > 4) robot.trail.push([robot.x, robot.y]);\n    }\n\n    // ------------------------------------------------------------ drawing\n\n    function render() {\n        const scale = canvas.width / WORLD_W;\n        ctx.setTransform(scale, 0, 0, scale, 0, 0);\n        ctx.fillStyle = '#fbfbf8';\n        ctx.fillRect(0, 0, WORLD_W, WORLD_H);\n        ctx.strokeStyle = '#111';\n        ctx.lineWidth = 14;\n        ctx.lineCap = 'square';\n        for (let y = 0; y < H; y++) {\n            for (let x = 0; x < W; x++) {\n                const o = maze.open[y][x];\n                const [px, py] = node(x, y);\n                if (o[0]) { ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(px + CELL, py); ctx.stroke(); }\n                if (o[1]) { ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(px, py + CELL); ctx.stroke(); }\n            }\n        }\n        const [sx, sy] = node(maze.start.x, maze.start.y);\n        ctx.fillStyle = 'rgba(22,163,74,0.25)';\n        ctx.strokeStyle = '#16a34a';\n        ctx.lineWidth = 3;\n        ctx.beginPath(); ctx.arc(sx, sy, 26, 0, Math.PI * 2); ctx.fill(); ctx.stroke();\n        const [ex, ey] = node(maze.end.x, maze.end.y);\n        ctx.fillStyle = '#111';\n        ctx.fillRect(ex - 30, ey - 30, 60, 60);\n        ctx.font = 'bold 12px system-ui, sans-serif';\n        ctx.textAlign = 'center';\n        ctx.fillText('END', ex, ey - 36);\n        ctx.fillStyle = '#16a34a';\n        ctx.fillText('START', sx, sy - 32);\n        K.drawRobot(ctx, robot);\n    }\n\n    let last = null;\n    function frame(now) {\n        if (last === null) last = now;\n        const dt = Math.min(0.1, (now - last) / 1000) * parseFloat(speedSel.value);\n        last = now;\n        if (state.running && !advance(dt)) { state.running = false; runBtn.textContent = 'Run'; }\n        render();\n        requestAnimationFrame(frame);\n    }\n\n    runBtn.onclick = () => {\n        if (state.phase === 'done') reset();\n        state.running = !state.running;\n        runBtn.textContent = state.running ? 'Pause' : 'Run';\n    };\n    document.getElementById('step').onclick = () => {\n        state.running = false;\n        runBtn.textContent = 'Run';\n        if (state.phase === 'simplify') {           // show the next reduction\n            state.simplifyT = 1;\n            advance(0);\n            return;\n        }\n        while (state.anim) advance(10);             // finish the current move\n        advance(0);                                 // read the sensors at the next node\n    };\n    document.getElementById('reset').onclick = reset;\n    document.getElementById('newMaze').onclick = () => { seed = Math.floor(Math.random() * 1e6); reset(); };\n    modeSel.onchange = reset;\n\n    const initial = new URLSearchParams(location.search).get('mode');\n    if (PHASES[initial]) modeSel.value = initial;\n    reset();\n    requestAnimationFrame(frame);\n})();\n</script>\n</body>\n</html>\n", "tachometer.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Tachometer - Kaizen Robotics live demo</title>\n<link rel=\"stylesheet\" href=\"assets/style.css\">\n<style>\n    .rig { display: grid; grid-template-columns: 360px 1fr; gap: 18px; align-items: center; }\n    @media (max-width: 800px) { .rig { grid-template-columns: 1fr; } }\n    #disc { width: 100%; max-width: 360px; height: auto; }\n    .scope { width: 100%; height: auto; border-radius: 8px; display: block; margin-top: 12px; }\n    #start { font-size: 16px; padding: 10px 18px; }\n</style>\n</head>\n<body>\n<header class=\"top\">\n    <a class=\"crumb\" href=\"index.html\">&larr; All demos</a>\n    <h1>Tachometer</h1>\n    <span class=\"tag\">Level 2 &middot; Arduino &middot; IR sensor &middot; 16x2 LCD</span>\n</header>\n<p class=\"lede\">\n    An IR sensor faces a rotating shaft that carries one reflective marker. Every time the marker passes, the\n    sensor output goes high. The sketch counts these pulses for a fixed time window and converts the count to RPM.\n</p>\n\n<main class=\"demo\">\n    <div>\n        <div class=\"panel\">\n            <div class=\"toolbar\" id=\"toolbar\"></div>\n            <div class=\"rig\">\n                <canvas id=\"disc\" width=\"720\" height=\"720\"></canvas>\n                <div>\n                    <div class=\"slider\">\n                        <span>Shaft speed</span>\n                        <input type=\"range\" id=\"rpm\" min=\"0\" max=\"3000\" step=\"10\" value=\"750\">\n                        <code id=\"rpmVal\"></code>\n                    </div>\n                    <h3>LCD</h3>\n                    <div id=\"lcd\"></div>\n                    <p><button class=\"btn primary\" id=\"start\">Press START button (D10)</button></p>\n                    <dl class=\"kv\">\n                        <dt>Pulses counted</dt><dd id=\"pulses\">0</dd>\n                        <dt>Window left</dt><dd id=\"left\">&ndash;</dd>\n                        <dt>Last result</dt><dd id=\"result\">&ndash;</dd>\n                    </dl>\n                </div>\n            </div>\n            <canvas class=\"scope\" id=\"scope\" width=\"1200\" height=\"120\"></canvas>\n            <p class=\"hint\">Scope: sensor output on D18 (high while the marker is in front of the sensor). Tip: use Speed 4&times; to skip through the 15 s window.</p>\n        </div>\n    </div>\n    <aside>\n        <div class=\"panel\" id=\"logic\"></div>\n        <div class=\"panel\">\n            <h2>The maths</h2>\n            <p>The sketch computes <code>RPM = pulses * 12 / 3</code>, which is <code>pulses &times; 4</code>.\n                With one marker per revolution that means the counting window is 60 s / 4 = <b>15 s</b>, and the\n                result can only change in steps of 4 RPM.</p>\n        </div>\n    </aside>\n</main>\n\n<section class=\"explain\">\n    <h2>How it works</h2>\n    <ol>\n        <li>The LCD asks you to press the button on D10 (it uses the internal pull-up, so a press reads 0).</li>\n        <li><code>count_pulses()</code> loops 1000 &times; 1227 times. Each time it sees D18 go high it adds one and waits for the marker to pass.</li>\n        <li>After the window it shows \"Please Wait\", then the RPM for 5 seconds, then asks again.</li>\n    </ol>\n</section>\n\n<script src=\"assets/kaizen.js\"></script>\n<script src=\"assets/firmware.js\"></script>\n<script>\n(function () {\n    const K = Kaizen, F = KaizenFirmware;\n    const lcd = K.lcd(document.getElementById('lcd'));\n    const table = K.decisionTable(document.getElementById('logic'), 'Sketch flow', [\n        { id: 'prompt', when: 'loop()', meaning: 'Wait for the button', action: '\"Please Press / Button to Start\"' },\n        { id: 'count', when: 'count_pulses()', meaning: 'Count markers for 15 s', action: '\"Reading RPM.....\"' },\n        { id: 'wait', when: 'delay(2000)', meaning: 'RPM = pulses * 12 / 3', action: '\"Please Wait.....\"' },\n        { id: 'show', when: 'delay(5000)', meaning: 'Show the result', action: '\"RPM=...\"' },\n    ], K.source('Level 2/Assignments/Tachometer_Assignment/Tachometer_Assignment.ino'));\n\n    const rpmIn = document.getElementById('rpm');\n    const shaft = { revs: 0 };\n    let pressedAt = -1e9;\n    const io = {\n        lcd,\n        startPressed: () => sim.t - pressedAt < 200,\n        revolutions: () => shaft.revs,\n        trace: id => { io.traceId = id; },\n    };\n    let fw;\n    const restart = () => { fw = new K.Firmware(F.Tachometer, io); io.pulses = 0; io.windowLeft = null; };\n    const sim = { t: 0, speed: 1, running: true };\n    restart();\n    document.getElementById('start').onclick = () => { pressedAt = sim.t; };\n\n    const MARKER = 25 / 360;        // marker width as a fraction of a turn\n    const sensorOn = () => (shaft.revs % 1) < MARKER;\n    const scope = K.scope(document.getElementById('scope'), [{ name: 'D18', color: '#fbbf24' }], 1000);\n    const disc = document.getElementById('disc'), dctx = disc.getContext('2d');\n\n    function drawDisc() {\n        const c = disc.width / 2, R = c - 60;\n        dctx.clearRect(0, 0, disc.width, disc.height);\n        dctx.save();\n        dctx.translate(c, c);\n        // sensor at the top\n        dctx.fillStyle = sensorOn() ? '#ef4444' : '#374151';\n        dctx.fillRect(-26, -c + 6, 52, 34);\n        dctx.fillStyle = '#9ca3af';\n        dctx.font = '20px system-ui, sans-serif';\n        dctx.textAlign = 'center';\n        dctx.fillText('IR', 0, -c + 30);\n        dctx.rotate(shaft.revs * Math.PI * 2 - Math.PI / 2);\n        dctx.fillStyle = '#1f2937';\n        dctx.beginPath(); dctx.arc(0, 0, R, 0, Math.PI * 2); dctx.fill();\n        dctx.fillStyle = '#f8fafc';\n        dctx.beginPath(); dctx.moveTo(0, 0); dctx.arc(0, 0, R, -MARKER * Math.PI * 2, 0); dctx.closePath(); dctx.fill();\n        dctx.fillStyle = '#6b7280';\n        dctx.beginPath(); dctx.arc(0, 0, 30, 0, Math.PI * 2); dctx.fill();\n        dctx.restore();\n    }\n\n    let last = null;\n    function frame(now) {\n        if (last === null) last = now;\n        const dt = Math.min(50, now - last);\n        last = now;\n        if (sim.running) {\n            const ticks = Math.round(dt * sim.speed);\n            for (let i = 0; i < ticks; i++) {\n                sim.t++;\n                shaft.revs += +rpmIn.value / 60000;\n                fw.step(sim.t);\n                scope.push(sim.t, [sensorOn() ? 1 : 0]);\n            }\n        }\n        drawDisc();\n        scope.draw(sim.t);\n        table.highlight(io.traceId);\n        document.getElementById('rpmVal').textContent = rpmIn.value + ' RPM';\n        document.getElementById('pulses').textContent = io.pulses || 0;\n        document.getElementById('left').textContent = io.traceId === 'count' ? (io.windowLeft / 1000).toFixed(1) + ' s' : '\u2013';\n        document.getElementById('result').textContent = io.lastRpm === undefined ? '\u2013' : io.lastRpm + ' RPM';\n        requestAnimationFrame(frame);\n    }\n    requestAnimationFrame(frame);\n    K.toolbar(document.getElementById('toolbar'), sim, { sound: false, onReset: restart });\n})();\n</script>\n</body>\n</html>\n"};
